using DigitalEvidenceSystem.Web.Data; using DigitalEvidenceSystem.Web.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace DigitalEvidenceSystem.Web.Pages;
[Authorize] public sealed class IndexModel(EvidenceDbContext db):PageModel { public int EvidenceCount{get;set;} public int ActiveCases{get;set;} public int ClosedCases{get;set;} public int PendingAnalysis{get;set;} public int CustodyCount{get;set;} public int UnverifiedIntegrity{get;set;} public string? Query{get;set;} public List<EvidenceItem> RecentEvidence{get;set;}=[]; public List<CaseFile> RecentCases{get;set;}=[]; public List<AuditLog> RecentActivity{get;set;}=[]; public List<EvidenceItem> Attention{get;set;}=[]; public List<(string Type,int Count)> Types{get;set;}=[]; public List<string> SearchResults{get;set;}=[]; public async Task OnGetAsync(string? q){Query=q?.Trim();EvidenceCount=await db.Evidence.CountAsync();ActiveCases=await db.Cases.CountAsync(c=>c.Status!="Closed");ClosedCases=await db.Cases.CountAsync(c=>c.Status=="Closed");PendingAnalysis=await db.ForensicAnalyses.CountAsync(a=>a.Status=="Pending"||a.Status=="In Progress");CustodyCount=await db.CustodyRecords.CountAsync();UnverifiedIntegrity=await db.Evidence.CountAsync(e=>e.IntegrityStatus!="Verified");RecentEvidence=await db.Evidence.OrderByDescending(e=>e.CreatedAt).Take(5).ToListAsync();RecentCases=await db.Cases.Where(c=>c.Status!="Closed").OrderByDescending(c=>c.UpdatedAt).Take(5).ToListAsync();RecentActivity=await db.AuditLogs.OrderByDescending(a=>a.OccurredAt).Take(6).ToListAsync();Attention=await db.Evidence.Where(e=>e.Status=="Received"||e.IntegrityStatus=="Hash mismatch"||e.IntegrityStatus=="Not verified").OrderByDescending(e=>e.UpdatedAt).Take(5).ToListAsync();Types=await db.Evidence.GroupBy(e=>e.Type).Select(g=>new{g.Key,Count=g.Count()}).OrderByDescending(x=>x.Count).Select(x=>ValueTuple.Create(x.Key,x.Count)).ToListAsync();if(!string.IsNullOrWhiteSpace(Query)){var evidence=await db.Evidence.Where(e=>e.Name.Contains(Query)||e.EvidenceNumber.Contains(Query)||e.SourceDevice.Contains(Query)).Select(e=>e.EvidenceNumber).ToListAsync();var cases=await db.Cases.Where(c=>c.CaseNumber.Contains(Query)||c.Title.Contains(Query)).Select(c=>c.CaseNumber).ToListAsync();SearchResults=[..evidence,..cases];}}}
